<template><section class="learning-editor"><h2>Learning rates & packages</h2><p>Set hourly prices by education level and format. Provider overrides take precedence. Packages may combine tutoring, small-group skill development, and counseling; eligibility and insurance are confirmed separately.</p><p v-if="error" role="alert">{{error}}</p><p v-if="saved" role="status">Saved.</p><h3>Hourly rate rules</h3><div v-for="(r,i) in catalog.rates" :key="i" class="learning-row"><select v-model="r.educationLevel" aria-label="Education level"><option v-for="v in levels" :key="v">{{v}}</option></select><select v-model="r.service" aria-label="Service"><option v-for="v in services" :key="v">{{v}}</option></select><select v-model="r.format" aria-label="Format"><option v-for="v in formats" :key="v">{{v}}</option></select><label>Dollars per hour<input type="number" min="0" step="0.01" :value="r.hourlyRateCents==null?'':r.hourlyRateCents/100" @input="r.hourlyRateCents=$event.target.value===''?null:Math.round(Number($event.target.value)*100)"/></label><button type="button" @click="catalog.rates.splice(i,1)">Remove rate</button></div><button type="button" @click="catalog.rates.push({educationLevel:'master',service:'tutoring',format:'virtual',hourlyRateCents:null})">Add hourly rate</button><h3>Packages</h3><article v-for="(p,i) in catalog.packages" :key="i"><label>Package ID<input v-model="p.id" placeholder="e.g. learning-six"/></label><label>Name<input v-model="p.name"/></label><label>Program<select v-model="p.program"><option v-for="v in programs" :key="v">{{v}}</option></select></label><label><input v-model="p.published" type="checkbox"/>Publish for families</label><div v-for="(c,j) in p.components" :key="j" class="learning-row"><select v-model="c.service" aria-label="Component service"><option v-for="v in services" :key="v">{{v}}</option></select><select v-model="c.educationLevel" aria-label="Component education level"><option v-for="v in levels" :key="v">{{v}}</option></select><select v-model="c.format" aria-label="Component format"><option v-for="v in formats" :key="v">{{v}}</option></select><label>Sessions<input v-model.number="c.sessions" type="number" min="1" max="100"/></label><label>Minutes each<input v-model.number="c.minutes" type="number" min="15" max="240"/></label><label>Package dollars/hour (blank = rate rule)<input type="number" min="0" step="0.01" :value="c.hourlyRateCents==null?'':c.hourlyRateCents/100" @input="c.hourlyRateCents=$event.target.value===''?null:Math.round(Number($event.target.value)*100)"/></label><button type="button" @click="p.components.splice(j,1)">Remove component</button></div><button type="button" @click="p.components.push({service:'tutoring',educationLevel:'master',format:'virtual',sessions:1,minutes:60,hourlyRateCents:null})">Add service component</button><button type="button" @click="catalog.packages.splice(i,1)">Remove package</button></article><button type="button" @click="catalog.packages.push({id:'',name:'',program:'tutoring',published:false,components:[]})">Add package</button><button type="button" :disabled="busy" @click="save">Save learning catalog</button></section></template>
<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({agencySlug:String});const catalog=ref({rates:[],packages:[]}),error=ref(''),saved=ref(false),busy=ref(false);
const levels=['secondary-student','college-student','associate','bachelor','master','doctorate'],services=['tutoring','skill-development','counseling'],formats=['virtual','in-person','small-group'],programs=['tutoring','academic-acceleration','bridge'];
watch(()=>props.agencySlug,async slug=>{if(!slug)return;try{catalog.value=(await api.get(`/public/agency-services/${encodeURIComponent(slug)}/learning-catalog/manage`)).data.catalog;}catch(e){error.value=e.response?.data?.error?.message||'Unable to load learning catalog.';}},{immediate:true});
async function save(){busy.value=true;error.value='';saved.value=false;try{catalog.value=(await api.put(`/public/agency-services/${encodeURIComponent(props.agencySlug)}/learning-catalog`,catalog.value)).data.catalog;saved.value=true;}catch(e){error.value=e.response?.data?.error?.message||'Unable to save learning catalog.';}finally{busy.value=false;}}
</script>
<style scoped>.learning-editor{margin:24px 0;padding:24px;border:1px solid #cddfe1;border-radius:12px}.learning-row{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:16px 0}.learning-editor label{display:inline-flex;flex-direction:column;gap:6px;margin:6px}.learning-editor input:not([type=checkbox]),.learning-editor select{max-width:200px;padding:8px;border:1px solid #bbcdd0;border-radius:5px}.learning-editor article{border:1px solid #ccd;margin:16px 0;padding:16px}.learning-editor button{padding:8px 12px;margin:6px}</style>
